// 听说与亲见分开标示；未来或远方真实位置不会被页面刷新，开工尚未完成时没有答复载荷。
#include "contact_inquiry_view.hpp"
#include "contact_inquiry_detail.hpp"
#include "contact_inquiry_receipts.hpp"
#include "resident/views/common_presentation.hpp"
#include <limits>
namespace hanmo::resident {namespace {
using V=BoundaryValue;using A=V::Array;
V identity(const WorldIdentity& s){StableId id;constexpr char hex[]="0123456789abcdef";for(auto b:s.world_id){id+=hex[b>>4];id+=hex[b&15];}return boundary::obj({{"world_id",V{id}},{"execution_epoch",V{s.execution_epoch}},{"revision",V{s.revision}},{"tick",V{s.tick}}});}
}
Outcome<BoundaryValue> query_contact_inquiries(const ContactInquiryViewAccess& read,Integer cursor){constexpr Integer limit=16;const auto& common=read.history.common;const auto& actor=common.state().metadata.player_actor_id;if(cursor<0||cursor>std::numeric_limits<Integer>::max()-limit)return {false,{},common_failure("InvalidContactInquiryCursor").error};if(!common.actor(actor))return {false,{},common_failure("UnknownPlayer").error};auto valid=validate_contact_inquiries(read.history,read.interaction,read.interaction_catalog,read.catalog,read.state,read.deaths,nullptr,read.exact);if(!valid.ok)return {false,{},valid.error};valid=validate_contact_inquiry_cached_results(common,&read.state);if(!valid.ok)return {false,{},valid.error};CommonPresentation names(common.state(),read.history.common_catalog);A all;
    for(auto at=read.state.started.order().rbegin();at!=read.state.started.order().rend();++at){const auto* s=read.state.started.find(*at);if(!s||s->contact.actor_id!=actor)continue;const auto* p=contact_inquiry_policy(read.catalog,s->policy_id);if(!p)return {false,{},common_failure("InvalidContactInquiryPolicy").error};auto provider=names.display_name(p->provider_actor_id),subject=names.display_name(p->subject_actor_id);if(!provider.ok||!subject.ok)return {false,{},provider.ok?subject.error:provider.error};const auto* f=contact_inquiry_detail::finished(read.state,s->fact_id);StableId status=f?(f->success?f->reply_kind:"interrupted"):"active";StableId progress="本次探听占用双方一个半日；尚未听完，不能提前查看答复。";
        V::Dict row{{"id",V{s->fact_id}},{"display_name",V{"向 "+provider.value+" 问 "+subject.value+" 的去向"}},{"status",V{status}},{"status_text",V{status=="active"?"正在当面询问":status=="known"?"听到原亲见消息":status=="unknown"?"对方没有可供答复的亲见记录":status=="declined"?"对方不愿透露":"会面中断"}},{"actions",V{A{}}}};
        if(f){row.emplace_back("finished_fact_id",V{f->fact_id});row.emplace_back("learned_tick",V{f->tick});if(!f->success)progress="本次会面未完成，没有新增去向消息。";else if(f->reply_kind=="unknown")progress="对方没有可用于这次答复的原亲见来源；没有推断人物现在的位置。";else if(f->reply_kind=="declined")progress="对方没有透露去向，也不能据此推断他是否知道。";else{const auto& answer=*f->answer;const auto* place=read.scene.places.find(answer.place_id);if(!place)return {false,{},common_failure("KnownContactPlacePresentationRequired",answer.place_id).error};auto label=names.text(place->name_key);if(!label.ok)return {false,{},label.error};progress="据 "+provider.value+" 说，他在半日 "+std::to_string(answer.observed_tick)+" 于 "+label.value+" 亲见该人。你在半日 "+std::to_string(answer.learned_tick)+" 当面听到；不确认对方现在仍在那里。";row.emplace_back("answer",boundary::obj({{"subject_actor_id",V{answer.subject_actor_id}},{"place_id",V{answer.place_id}},{"source_fact_id",V{answer.source_fact_id}},{"source_kind",V{answer.source_kind}},{"observed_tick",V{answer.observed_tick}},{"learned_tick",V{answer.learned_tick}},{"heard_from_actor_id",V{p->provider_actor_id}},{"reliability",V{StableId{"reported_last_seen"}}},{"current_location_confirmed",V{false}}}));}}
        row.emplace_back("progress_text",V{progress});all.emplace_back(std::move(row));
    }
    for(const auto& p:read.catalog.policies){auto declaration=preview_authored_provider_source(common,read.interaction,read.interaction_catalog,read.interaction_access,actor,p.provider_actor_id);if(!declaration.ok){if(declaration.error.kind!=ErrorKind::rule)return {false,{},declaration.error};continue;}const auto& m=declaration.value.meeting;if(m.context.role_id!=p.role_id||m.dialogue_id!=p.dialogue_id||m.node_id!=p.node_id||p.subject_actor_id==actor)continue;auto quote=preview_contact_inquiry(common,read.interaction,read.interaction_catalog,read.interaction_access,read.catalog,read.state,actor,{p.id},read.exact);if(!quote.ok&&quote.error.kind!=ErrorKind::rule)return {false,{},quote.error};auto provider=names.display_name(p.provider_actor_id),subject=names.display_name(p.subject_actor_id);if(!provider.ok||!subject.ok)return {false,{},provider.ok?subject.error:provider.error};A actions;actions.push_back(boundary::obj({{"command",V{StableId{contact_inquiry_action_kind}}},{"params",boundary::obj({{"policy_id",V{p.id}}})},{"text",V{StableId{"当面问清去向"}}},{"summary",V{"与 "+provider.value+" 用一个半日谈 "+subject.value+" 的去向；可能只得旧消息、不知道或不愿透露。无费用或额外关系奖励。"}},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:quote.error.original.code}}}));all.push_back(boundary::obj({{"id",V{"policy:"+p.id}},{"display_name",V{"问 "+provider.value+" 关于 "+subject.value}},{"status",V{StableId{"available_topic"}}},{"status_text",V{StableId{"眼前本人可谈的话题"}}},{"progress_text",V{StableId{"实际会面占用双方一个半日。确认前不会提前透露答复或判断对方所知。"}}},{"actions",V{std::move(actions)}}}));}
    A rows;const auto end=std::min(all.size(),static_cast<std::size_t>(cursor+limit));for(auto i=static_cast<std::size_t>(cursor);i<end;++i)rows.push_back(std::move(all[i]));V::Dict page{{"ok",V{true}},{"source_identity",identity(common.state().identity)},{"observer_actor_id",V{actor}},{"cursor",V{cursor}},{"rows",V{std::move(rows)}}};if(end<all.size())page.emplace_back("next_cursor",V{cursor+limit});return {true,V{std::move(page)}, {}};
}
}
